import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error in your code: {e}')

# Check for pandas import
found_pandas = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'pandas' for name in node.names):
        found_pandas = True
    if isinstance(node, ast.ImportFrom) and node.module == 'pandas':
        found_pandas = True

if not found_pandas:
    raise AssertionError('Task 1: Missing import pandas (check syntax)')

# Check for pd.DataFrame() call
found_dataframe = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == 'pd' and node.func.attr == 'DataFrame':
                found_dataframe = True

if not found_dataframe:
    raise AssertionError('Task 2: Missing pd.DataFrame() call')

# Check for .head() method call
found_head = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute) and node.func.attr == 'head':
            found_head = True

if not found_head:
    raise AssertionError('Task 3: Missing .head() method call')

# Check for .dtypes attribute access
found_dtypes = False
for node in ast.walk(tree):
    if isinstance(node, ast.Attribute) and node.attr == 'dtypes':
        found_dtypes = True

if not found_dtypes:
    raise AssertionError('Task 4: Missing .dtypes attribute access')

# Check for print statements (at least 2)
print_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and 
               isinstance(node.func, ast.Name) and node.func.id == 'print']

if len(print_calls) < 2:
    raise AssertionError('Tasks 3 & 4: Expected at least 2 print statements')

print('TEST_PASSED')
